def prepare():
 old=Path(REFS['old_run']);plan=read(old/'PLAN.json');audit=read(Path(REFS['v1_benchmark'])/'evidence/RAW_AUDIT.json');reg=build_registry(plan['cells']);reader=PayloadReader();proof=validate_registry_against_plan(plan,reg,audit,reader);write(ROOT/'REGISTRY.json',reg);write(ROOT/'PLAN.json',plan);proof2=validate_registry_against_plan(read(ROOT/'PLAN.json'),read(ROOT/'REGISTRY.json'),audit,reader)
 reqs=[];summaries=[]
 for s in plan['requests']:
  req,trace=capture_real_request(s,read(ROOT/'REGISTRY.json'),REFS['candidate_run']);validate_actual_request(req,s,reg,REFS['candidate_run'],reader);a=admit(req,s,plan,reg,REFS['candidate_run'],reader);reqs.append({'slot':s['slot'],'request':req});summaries.append({'slot':s['slot'],'run_namespace':REFS['candidate_run'],'task':s['task'],'recipient':s['recipient'],'state':s['state'],'donor':s['donor'],'direction':s['direction'],'mode':s['mode'],'repeat':s['repeat'],'stage':s['stage'],'order':s['order'],'cuts':req['boundary_cuts'],'KV':req['restore100']['KV'],'initial_logits':req['restore100']['logits'],'normalized_request_sha256':a.request_sha256,**trace})
 write(ROOT/'ACTUAL_REQUESTS.json',reqs)
 for row,s in zip(read(ROOT/'ACTUAL_REQUESTS.json'),plan['requests']):require(row['slot']==s['slot'],'roundtrip slot');validate_actual_request(row['request'],s,read(ROOT/'REGISTRY.json'),REFS['candidate_run'],reader)
 write(ROOT/'ACTUAL_REQUEST_SUMMARIES.json',summaries)
 # Independently reproduce the old double-path mismatch from native REQUEST/RESULT, without reclassifying it.
 oldreg=read(old/'DONORS.json');bad=registry_mismatches(plan,oldreg);require(len(bad)==28 and {x['recipient'] for x in bad}=={'A'},'old collision diagnosis changed');failed=read(next((old/'receipts').glob('*.json')));record=read(next((old/'records').glob('*.json')));raw=read(old/record['raw_path']);request=read(old/record['raw_path'].replace('.RESULT.json','.REQUEST.json'));require(sha(old/record['raw_path'])==record['raw_sha256'],'old raw changed');s=failed['slot'];require(request['restore100']['KV']==raw['restore100']['KV_source']==oldreg[s['task']+'|'+s['state']]['KV'],'actual second lookup linkage');require(raw['restore100']['post_restore_KV_sha256']!=s['mixture_spec']['sha256'],'expected/actual old input unexpectedly equal');life=read(old/Path(record['identity_path']).parent/'LIFECYCLE.json');ledger=[loads(x) for x in (old/'LEDGER.jsonl').read_text().splitlines()];require(sum(x['event']=='OWNED_PID' for x in ledger)==sum(x['event']=='REQUEST_STARTED' for x in ledger)==1,'old accounting changed')
 oldproof={'status':'REPRODUCED_NOT_REPAIRED','conflicts':bad,'logical_cells':56,'mismatched_recipient_A_cells':28,'source_of_fault':'plan mixture prechecked, then original Worker.request re-read task|state registry','failed_slot':s['slot'],'expected_KV':s['mixture_spec'],'actual_requested_KV':request['restore100']['KV'],'raw_sha256':sha(old/record['raw_path']),'request_sha256':sha(old/record['raw_path'].replace('.RESULT.json','.REQUEST.json')),'old_processes':1,'old_requests':1,'old_target_decodes':raw['target_decode_calls'],'old_owned_seconds':life['owned_seconds'],'scientific_qualified_samples':0,'old_status':failed['status'],'old_unstarted_slots':167};write(ROOT/'OLD_FAILURE_AUDIT.json',oldproof)
 # Frozen assets and driver files are CPU-read only. Live CIM inspection launches PowerShell, never native model code.
 f=read(old/'F0.json');assets=[]
 for pin in f['bindings']:p=Path(pin['path']);require(p.stat().st_size==pin['bytes'] and sha(p)==pin['sha256'],'frozen asset changed: '+str(p));assets.append(pin)
 ps='C:/Windows/System32/WindowsPowerShell/v1.0/powershell.exe';cmd="[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new(); Get-CimInstance Win32_VideoController | Select-Object Name,PNPDeviceID,DriverVersion | ConvertTo-Json";live=loads(subprocess.check_output([ps,'-NoProfile','-NonInteractive','-Command',cmd],creationflags=subprocess.CREATE_NO_WINDOW).decode('utf-8-sig'));driver=next(x for x in live if 'DEV_E20C' in x['PNPDeviceID']);require(driver==f['driver_identity'],'live driver changed');write(ROOT/'ASSET_RECEIPT.json',{'status':'PASS_CPU_HASH_AND_LIVE_CIM_ONLY','bindings':assets,'driver_identity':driver,'native_load_offload_memory_watchdog_qualification':'PENDING_SEPARATELY_AUTHORIZED_NATIVE_RUN','new_native_processes':0,'new_forwards':0})
 write(ROOT/'ADMISSION_RECEIPT.json',{'status':'READY_FOR_REVIEW_CPU_ONLY','native_authorized':False,'logical_cells':56,'logical_entries':64,'actual_requests':168,'actual_serialized_roundtrips':168,'original_request_method_sha256':REFS['source_modules']['controller100.py']['sha256'],'source_to_registry_validation':proof,'disk_roundtrip_validation':proof2,'coverage_matrix':[
 {'edge':'plan -> registry','scope':'all 56 cells /168 slots, logical coordinates + actual fixed PR103 bytes','verified':True},
 {'edge':'registry -> actual serialized request','scope':'original Worker.request AND Worker.send, all168; one real lookup each','verified':True},
 {'edge':'actual request -> expected import','scope':'full restore100/prompt/cuts/mode/recipient logits plus payload pins','verified':True},
 {'edge':'preverified object -> sender','scope':'same object, no second registry lookup, mutation/identity/payload guards before first forward','verified':'CPU_NEGATIVE_CONTROLS_ONLY'},
 {'edge':'expected import -> native result gate','scope':'independent source/reeserialization/endpoint and separate counts/heavy gate retained','verified':'IMPLEMENTED_CPU_TESTED_NATIVE_V2_NOT_RUN'}],
 'old_cost':{'processes':1,'requests':1,'target_decode':127,'owned_seconds':life['owned_seconds']},'proposed_new_budget':{'new_starts':168,'stage_starts':[16,32,40,80],'owned_seconds':21600,'new_output_bytes':4*1024**3,'probes':0,'warmups':0,'retries':0},'combined_v1_plus_candidate_v2_max':{'starts':169,'owned_seconds':21600+life['owned_seconds']},'candidate_run_NOT_CREATED':REFS['candidate_run'],'next_step':'WAIT_EXPLICIT_AUTHOR_APPROVAL_OF_NEW_BUDGET_AND_NEW_F0'})
 print(json.dumps({'status':'READY_FOR_REVIEW_CPU_ONLY','cells':56,'actual_requests':168,'old_conflicts':28,'new_native':0}))
